) AS (
  VALUES 
    (147::BIGINT, 'La clase es aburrida en sí, pero la profe es super buena gente. Si usted le entrega cosas después de tiempo ella no tiene problema, siempre y cuando no sea demasiado. Trabaja bastante en grupos y siempre está pendiente de que si se aprenda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-13T00:00:00+00:00'::TIMESTAMPTZ, '4cc9a273bdf408f0afe0bfa4125482096b8203b1a11331a110eadde1dc745715'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'El curso es re-fácil, se pasa solo haciendo los trabajos, pero con ella se hace demasiado aburrido. Se ve que sabe y ella no cae mal, pero deja demasiados trabajos y las clases son muy largas. Casi nunca contesta a mensajes con dudas y dura demasiado en calificar'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, '5941eaab8871b7e1f7689722046a55c78472d65cd2bb1173365ad5d2cfa97f02'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Buena profe y además juega WoW, tipaza'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2026-03-29T00:00:00+00:00'::TIMESTAMPTZ, 'd05fa7e1a69050196f7c0c8f6e415c32fa2fb07829219563ff607ddd4661f4e0'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'Excelente profesora! No estresa, enseña muy bien y es muy respetuosa, balance perfecto entre vacilona y profesora que se toma enserio.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-03-25T00:00:00+00:00'::TIMESTAMPTZ, 'a59ef09f47e3f6f248e970a89488796f113e9c0980b4cdb9535d2d59f22b2155'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'La profe es buena persona aunque a veces se le notan los favoritismos, no creo que sea una mala opción pero simplemente siento que la clase no me terminó de capturar. Es obligatorio participar en todas las actividades, presentaciones y debates (básicamente porque de eso es el curso).'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2026-02-09T00:00:00+00:00'::TIMESTAMPTZ, '2e3bcba395045d61473830c71fdde21a56af083422c37ef3b52ff8733aec6cce'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'Profe de muy mala, muy necia e insistente. Su clase se pasa sola pero es increíblemente molesta. Suele ser detestable y necia con tonteras. Si no le importa el profe, matricule con ella, el curso se pasa solo, pero cada que hay clases dan ganas de meterse un tiro. pero no es mala persona'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-02-09T00:00:00+00:00'::TIMESTAMPTZ, '383de394bdaa8269475cd0a512b74704919c3786cd1081048a3f134d9e025bae'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'La profesora es excelente, carismática y con actitud comprensiva. Asigna bastantes trabajos, pero son sencillos y contribuyen al aprendizaje. Brinda confianza a los estudiantes durante las exposiciones y realiza correcciones de manera clara y respetuosa, generando un ambiente de confianza en clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2025-12-27T00:00:00+00:00'::TIMESTAMPTZ, 'cdaf0e3be0e303f2c3a15cb2e5307c82e23baddf7916d73406949ef5f8dcf0b6'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'Es una profesora que sabe mucho y brinda bastante apoyo. Es muy desordenada y entrega notas a último momento, por lo que usted no sabe como va hasta el final. Pide avances y nunca los revisa ni le hace correcciones, hasta la entrega final. Pero si le pone con entregar los trabajos, se pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'dffa19796e45e71f2d6811aee575c2b261f35a1aae1f06bf90ca29014082ce88'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'La profesora es un amor de persona! Caliica de forma muy justa y es muy buena dando clases, y super comprensiva en temas de entregas tardias y de justificaciones. Super recomendada, pero no le quedes mal con trabajos! Ella perdona siempre que seas honesto y a tiempo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Clases excelentes']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '92d8183bce2fe8934a77d39efcb9665710b374dc753e6e7450960d504338fcd7'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'Excelente profe, muy abierta y comprensiva. Hay que estar recordandole algo en especifico pero muy buena profe, la recomiendo 100, se pasa facil , se aprende bastante. No le hace falta incomodar en las evaluaciones orales a los estudiantes para que lo hagan bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2023-11-22T00:00:00+00:00'::TIMESTAMPTZ, '625836b2d1975f913e0f84a9bf1284396a3094939b0b26cf9f863ff377fb9845'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'Es una buena profesora, es un poco desordenada con el tema de las notas pero hace que el curso sea bastante fácil.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Inspirador']::TEXT[], '2023-11-21T00:00:00+00:00'::TIMESTAMPTZ, '82d99cb42e34d98e2a3c621bdee0001fd0924789aad1cc0e76f30c076d73a30f'::TEXT, ARRAY[556]::BIGINT[]),
    (147::BIGINT, 'Buena profesora, es simpática, y brinda apoyo a los estudiantes. Las presentaciones si son un poco aburridas, pero nada del otro mundo, las tareas, proyectos y asignaturas que deja son geniales para explorar la carrera que uno escogió , La recomiendo, matricule con ella, la clase se pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-11-20T00:00:00+00:00'::TIMESTAMPTZ, '622c409bedf7f5ec8b33f426c1fad471bc8de8564caed975cede3061da969ce0'::TEXT, ARRAY[556]::BIGINT[]),
    (147::BIGINT, 'Es muy simpática y buena gente. El problema es que es algo desordenada con el curso (se lleva fácil) pero no se aprende tanto como se debería.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2023-11-02T00:00:00+00:00'::TIMESTAMPTZ, '022b776980ddd91a1a2b427eeed1290b10ef4b4fed5b0da63d0824e322f99c80'::TEXT, ARRAY[556]::BIGINT[]),
    (147::BIGINT, 'Es una profe muy agradable y explica los temas con bastante claridad. Siempre está dispuesta a aclarar dudas y ayudar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '5dc154e4d554dcc733569957014b8a044754df5cfebbd36f829b492eb6d46d95'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Como persona es muy agradable y si hace ameno el tiempo de clase en ese sentido. Pero es demasiado desordenada. Siempre entrega notas tardísimo y suele cancelar muchas clases. Se pasa fácil el curso pero no se aprende tanto como con otros.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '9cbcde14a5b2935312eb8c690bfbdddbabe5bf5a22c94cdc682f64697978b880'::TEXT, ARRAY[556]::BIGINT[]),
    (147::BIGINT, 'La profe es un poco desordenada con las entregas y cancela muchas clases. Siempre está como en otras.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2023-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'd1b4d543bc9afd851669e619e96eee7c672f23a0c4bdd188ec8c1b76c15a0421'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, '904c08daf4aaf61e63f9deec6579b26dba027da57aab7d3b2c6f1efd84f392e9'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-08-04T00:00:00+00:00'::TIMESTAMPTZ, 'ebefb93a7de8c7c122ad2101ec486f450cde1479e0705f67a1bfa58d83431a43'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'Conoce muy bien su área, es muy inteligente y sabe de lo que está hablando. Un taller con ella sería increíble. Sin embargo, como profesora es desordenada, entrega notas tarde, las rúbricas son algo confusas y puede ser complicado ponerse en contacto con ella.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2022-07-19T00:00:00+00:00'::TIMESTAMPTZ, 'ef4a0480bd19d9b983ad9c9518177a38378feaac6632bbb4dcfdcc06c57063f0'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Deja trabajillos pero no califica rudo. La clase era medio larga pero entretenida.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2022-07-02T00:00:00+00:00'::TIMESTAMPTZ, '084fd4252f977e9909e7881b21fd3ece206ccf12c4cac2442f9a75910ab36126'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Es muy desordenada. Califica hasta semana 18 y parece que fuera al azar. La rúbrica suele ser muy confusa.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '586826d922b906006d8067f63ba3fb3064973f39cbd906e925a458bfc66e6f5e'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Una profesora excepcional! Las clases y trabajos están estructurados de una forma que uno se siente como un personaje de los libros de Tolkien. La creatividad y motivación estarán en su máximo todo el tiempo. Es muy amable y siempre está atenta a consultas. 100% recomendada!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2022-01-28T00:00:00+00:00'::TIMESTAMPTZ, '6093d9e0f629fed7b56f943171ca1aee71da6ed01412e2b62e7ce76debe49ada'::TEXT, ARRAY[765]::BIGINT[]),
    (147::BIGINT, 'No es tan mala, lo que si es muy desordenada y las calificaciones las da hasta lo último, las tareas semanales no tienen valor alguno solamente lo que se entrega por el TEC Digital o el cuaderno de teams, es muy comprensiva y da más tiempo si nota que usted le pone.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '442ac252cdbc221ce7ea999c62065979d78b5e17dbbe3d17e05468b6b9718f95'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'La profe ayuda bastante pero si es un toque desordenada.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '13b05ecc01d4d56de8857139ccb41ecc061b43c8b77d34f163313cbec40992d3'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Las evaluaciones son un desorden y casi no explica. La clase es aburrida y cuesta que contactarla para dudas.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas']::TEXT[], '2021-07-04T00:00:00+00:00'::TIMESTAMPTZ, '87906a0611003b9b2111fd2cc241bada03069534e9921caad9346ffaa0aaad1e'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Super buena profe, yo tenía miedo de matricular con ella por los comentarios pero nada que ver. Super comprensiva con las dificultades que uno pueda tener y se ve que le gusta enseñar. La recomiendo full. Las presentaciones se pueden entregar en video y nada más es de dedicarle un poquillo de tiempo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, '5461c20232ff94d9b69729ba79ec8bc500a88dc125a9a153d8b2c20e276a95f1'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'En virtual fue muy tranquila. Sí tiene que dedicarle tiempo a las presentaciones y los videos (solo como dos videos nos pidió) pero si usted tiene facilidad para hablar se le va a hacer un queque. Igual ella es super comprensiva con la gente que no tiene tanta facilidad. Muy buena'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'c8fb0c652dd75b268815813bdbad2856177e2a4d38a00d142826c4f0b5ce07d3'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'En la modalidad virtual, lo hizo liviano, fue muy chill. Toma lista pero se puede faltar a las primeras clases claro, al final siempre se entregan la misma cantidad de trabajos pero es muy pura vida y comprensiva'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2021-01-18T00:00:00+00:00'::TIMESTAMPTZ, '013054666c96fa919c529c875821c864afdbbb2443e8bb14f972b83e251ad4e7'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-12-17T00:00:00+00:00'::TIMESTAMPTZ, '6a0d8c7de66b03c75d93c59fb07a1f66483749b5b80c9cd6e19b332d89259055'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'Bastante buena dando este CFH.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2020-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'cb3d234d8ebf5c4080b270034212274bc6691bdbc7b62030fe979c5752060832'::TEXT, ARRAY[765]::BIGINT[]),
    (147::BIGINT, 'Excelente profesora, excelentes explicaciones, califica duro, pero a quien le pone se beneficia con ella'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'e3de5ac966cf2f1d4fc0a5ace7e988cffd55ed8140a1b078246299dee34108d6'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'La profe es muy pura vida, califica un poco duro, pero para la modalidad virtual entiende al estudiante, además ayuda con las fechas de entrega de los trabajos, la verdad si se aprende pero hay que dedicarle tiempo'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, 'b1ab12505756289abd0a77ce34548c661552a30492bef53e1c2d8dc12d8d7db0'::TEXT, ARRAY[556]::BIGINT[]),
    (147::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Muchos proyectos grupales']::TEXT[], '2020-02-17T00:00:00+00:00'::TIMESTAMPTZ, '17a2677161dc540a26b89ecd5227f8fcf0049189b59ed52e2958519925a0a265'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'La profe es pura vida, el curso es un poco tedioso pero si se preparan con tiempo y le piden apoyo y consejos ella siempre los va a atender.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2019-12-18T00:00:00+00:00'::TIMESTAMPTZ, '837cb4f44b9b0f1591f00d74729c88c24f410ccb3d86063494a3977cfe028aed'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'Sin duda, la peor profesora de todo el tec, definitivamente con tan baja calificación no sé porque no la han reubicado o echado, no tiene respeto con los estudiantes y no responde ni aclara dudas, no recomiendo que matriculen ni un solo curso con esta profesora.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2019-10-12T00:00:00+00:00'::TIMESTAMPTZ, 'd780eaf4405a590f88e58c91ffe7c7950db7b38eeb7534c35d6202bdb23aaee3'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'La peor profesora que he tenido en todos mis años en el Tecnológico, no tiene una gota de respeto hacía los estudiantes'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2019-05-16T00:00:00+00:00'::TIMESTAMPTZ, '8a880521ed16270fcea22f1806fbbeb45e820bd3dd49f566cf4c70eb157d5814'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'Buena profe, solo que es estricta con la asistencia y la puntualidad. Siempre dispuesta a ayudar, es solo de prepararse adecuadamente para las presentaciones.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, '153de7644713de9e78b14aab0bf6ce948ad8f828cc2cabf857e2ac32d41f430a'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2018-11-10T00:00:00+00:00'::TIMESTAMPTZ, '04d35615b8dae7b79bc50268f06152630d4be34815d66de22bb3b70ef84a2274'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2018-11-04T00:00:00+00:00'::TIMESTAMPTZ, '1a9f3be29a504a7afebe4bd45dfe474e441efb3ea87bfe43b194ae5ff347b621'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'El curso es muy relajado, nada más hay que trabajar en las 2 exposiciones finales y entregar el documentos de los charlas y listo. De hecho es aburrido en ocasiones y jode mucho con la asistencia.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '8b62fa13d16af54c9146decb3d3bcbc85b276e4dd0740da2bc187cba1caac280'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'Es súper estricta con la asistencia. Deja trabajos largos. Califica duro. Es pura vida.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'd686b4eda1c415b43bfccc747529c8a13c60d0ac12a2086f6fcdf2ae0b105704'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Califica duro pero enseña bien la materia. Con seguir las indicaciones y recomendaciones que pone en los trabajos se pasa fácil. Super estricta con la asistencia asi que es importante llegar a clase y hacerlo a tiempo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2018-06-19T00:00:00+00:00'::TIMESTAMPTZ, '6aa1ff1d102f72f877bc1d95917d112cf2623bb35f53470657bdb5be23432487'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Es una buena profesora y es buena gente. Solo hay que dedicarle tiempo a los trabajos y se pasa bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, '2b5675eb500deaf76a085fb70c95f304869aeb35e7e53f47ad70b1765acd68bc'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'La mae es buena nota, pero le da igual si uno trabaja y no puede llegar a tiempo por inconvenientes, ni si quiera es que uno llega tarde por gusto'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2017-11-08T00:00:00+00:00'::TIMESTAMPTZ, '41b44478325b4bace523a023687f05c023d6de05ec40ab035ec67a6aece984a3'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'Es estricta.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas']::TEXT[], '2017-09-21T00:00:00+00:00'::TIMESTAMPTZ, 'c9b9bc7c18657803d34715672cc6fbaf28004c6f598d51a928d162fc437bc353'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'Es una profe que deja muchos trabajos pero a la vez es comprensible con la carga académica, si usted no puede entregarle un trabajo ella siempre da más tiempo, hay que dedicarle tiempo al curso y se pasa fácil. Casi siempre llega tarde pero es pura vida'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '267f44a6ed786ce2b305425f622e0baa228b8387aa8965a87599d6b45709e2d1'::TEXT, ARRAY[556]::BIGINT[]),
    (147::BIGINT, 'Excelente profesora, ayuda bastante cuando pasa los trabajos de fecha por la carga academica en otras materias, rubros de calificacion claros, hacer todos los trabajos y pasa facil con buena nota. Nota aparte: aveces llega tarde.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '5b9eca5d0105f8c9e7a3872daee1dd500b18c3fbebcb84cd25591440aa241b1f'::TEXT, ARRAY[556]::BIGINT[]),
    (147::BIGINT, 'Califica duro pero justo, yo hubiera pasado el curso de no ser que no pude entregar un trabajo, ayuda bastante y aun más si eres de adecuación, a veces llega tarde, la recomiendo mucho'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '05794d688484ce013d31b885e1a580e778d1f35e1574dfca520f7c603f4922dc'::TEXT, ARRAY[556]::BIGINT[]),
    (147::BIGINT, 'Para comu oral es muy tranquila, no pide tanto.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '75f88ea9e515e18ec28a0b1bea616b887ffd2e0b4078961e70df5637fc692774'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'Califica duro y da más que otros profesores, pero de que uno aprende , aprende'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'f8f8e1082fd3bc48a18f5f730147dc0b44e9717f8b0cb2489068e04f27d33b56'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'Bastante estricta calificando'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-03T00:00:00+00:00'::TIMESTAMPTZ, '9f1b612972f453b745da41ee21d5a6216bf288222431f2cb79a66b9d5f7e2d5c'::TEXT, ARRAY[503]::BIGINT[]),
    (147::BIGINT, 'Si deja mucho trabajo en comparación con otros profesores, pero siento que ella no califica muy rudo y es buena persona. Se aprende pero recomiendo que si puede matricule con alguien más.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2017-03-31T00:00:00+00:00'::TIMESTAMPTZ, 'fcca610188c34ef2fad745d889bc47e29305d876b2e5bc5fb8f82d175e7ba00f'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2017-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'b48425c45205b57fe5d4df7a456bd2953700e6d6e72a9045e0d232a686cdce96'::TEXT, ARRAY[556]::BIGINT[]),
    (147::BIGINT, 'Para aprender de verdad es buena, sin embargo un curso de un credito lo vuelve en un curso de 3 creditos. MUY estricta y para las exposiciones es dura calificando'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'ebb71c97c21f52a1927ade730205760bceae4255c50bfa31fb9cd174dd554671'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'Definitvamente sobra decir algo, ella es buena profe, lo que pasa es que no se ubica en el curso que está dando, quita demasiado tiempo con los trabajos, las exposiciones tienen que ser perfectas para sacar más de 90 y suele ser incluso prepotente, podría meter con otro profe mejor'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2017-01-24T00:00:00+00:00'::TIMESTAMPTZ, '6802b91c1b18314cc4be1e88e1206361342af2b137b334ac1919e44f2048ed0d'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Es muy buena persona y si se aprende pero si no quiere invertir muchas horas en este curso,mejor ni matricule con ella ya que los trabajos que deja son muy largos.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'eb79f8b7ddeb74448e881b7204447c4b5bba89bacf2951db9fdf4209d024c0e5'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Muchísimo trabajo! cree que es el único curso que uno lleva... No la recomiendo.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2017-01-12T00:00:00+00:00'::TIMESTAMPTZ, 'fcdcb701f5d603a42c782c29ef022f84d497d86e8ad6c9c1b64de2cbf5ca6cae'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'es super super super estricta. se aprende. un poco intensa pero cae bien. si la guila la agarra contra uno le va hacer imposible el curso entonces mejor llevarse bien con ella y ser responsable para que no lo agarre entre ojos'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-03T00:00:00+00:00'::TIMESTAMPTZ, '00feb0f136213151381a54990c1694bb99572561bcee580cd72bccd347cb4538'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'Hace el curso mucho más difícil de lo que debería, califica duro y no es nada clara con las instrucciones. No la recomiendo'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '9ef2990b556f7fb9f6f13dc35e7fe8cfbb12ad3d12acfe8772185fc665bcddae'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '7cf2920ee003dcbcf9c0974966913cb88b7e1c64a12383339a5df9c576c8a99d'::TEXT, ARRAY[556]::BIGINT[]),
    (147::BIGINT, 'Deja trabajos muy largos y califica muy duro, se aprende mucho y es buena como persona pero como profesora es estricta. No matricule con ella a menos que le guste redactar y leer.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'cb89c4f93f7e2690b56e3e9e7f999d8ecc4602a6647b09a10b5dca65fa8ec382'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '456a1e8713d22c5ce6cca482fe3cb1f05938dfe0c52181ee871c92fa2a942f99'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'El curso es bien fácil. No deja muchos trabajos y consiste más en asistencia y charla grupal de las lecturas.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '99c0f73466d17492c6aa2f95da8874a79142394ac4556118cb9659b59fa076bf'::TEXT, ARRAY[503]::BIGINT[]),
    (147::BIGINT, 'A pesar de que genera un ambiente de confianza en las clases califica muy duro y requiere más dedicación en comparación con otros profesores'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, '7df7e4711f33971934c07f784eef592fc4870bf464b6f241cad435aeaba8a0d5'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'La profe es buena gente y explica bien. Pero deja demasiadas lecturas, trabajos muy largos y califica a morir. Si lo puede llevar con otra profe se lo recomiendo.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2016-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'ecdbdc073dbb077e8c4bc0b5cd0ed80b779d0f4ac283ba9d639348405558d1ea'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Deja muchísimos trabajos y muy extensos. Califica muy duro, poco comprensiva. Si quiere pasar el curso debe dedicarle muchas horas a los trabajos asignados!'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2016-06-17T00:00:00+00:00'::TIMESTAMPTZ, '55e5376108525974d448ba141cc2368d9288d0023065bde55e4b49c9407fa3d6'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Pasar el curso es muy difícil con esta profesora'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'bf75449612cc3ab66dfde555ad075875cdf0d434fee0697832660ea3a554e8db'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Deja trabajos demasiados trabajos largos y duros. Pierdo más tiempo haciendo los trabajos de ella que en todo el resto de los cursos combinados (y llevo bloque completo de Meca). Califica exageradamente duro y se aprende muy poco. Es casi imposible pasar sin importar lo que uno se esfuerce.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2016-06-03T00:00:00+00:00'::TIMESTAMPTZ, '709485399104850b1c270b01ed76eab9d8b2ffd68a029dafa1ec7fa330ec7a7c'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'No metan con ella, mejor esperar un semestre, igual si lo llevan es casi de fijo que lo pierden por mas que se esfuercen en los trabajos.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2016-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'd9150a47908d1b5f279b98077fb8135e0c7b3a71a0de8957dee7d297da29c774'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Es bastante mala profesora, deja trabajos larguísimos. Mejor mátense'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2016-05-26T00:00:00+00:00'::TIMESTAMPTZ, '0b355d9cc3b8eb9442dc202a16933d677b3150fbeb4b9e5acdfc293351caf490'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Es una pésima profesora, piensa que uno ya esta al nivel de ella para redactar, nunca matriculen con ella ni aunque fuera la unica opcion'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2016-04-28T00:00:00+00:00'::TIMESTAMPTZ, 'fddafa59b671b5566b1e5a2ddfb93931acd9e2055ed2ac26f2638fb0052c3e48'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Califica muy rudo. No genera interés en su clase.No facilita de manera alguna el proceso de aprendizaje.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2016-04-24T00:00:00+00:00'::TIMESTAMPTZ, '1b8aa0999275911a71875afb5c3172716c1c196cce3e5aa392fd13061d979be6'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'Pesima, convierte una clase facil en dificil y deja muchos trabajos. No sabe explicar, muy malhumorada.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-28T00:00:00+00:00'::TIMESTAMPTZ, '78b4c73d2512f5ea62764f222002239f55efcba1894dbc22a2ce7f6ddcc9d4f5'::TEXT, ARRAY[600]::BIGINT[]),
    (147::BIGINT, 'Para verano es "relajada", pero si deja trabajos, lo único aburrido es que es demasiado estricta, no deja que uno saque el celular, además le molesta muchísimo la gente que se duerme en clase.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-21T00:00:00+00:00'::TIMESTAMPTZ, '7a88371301693537a34abf0bfb59212dbbba9a49669a9a97013553886613fc44'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'hace el curso muy aburrido xq sus clases son muy rutinarias y apagadas, es exigente y califica duro. Manda bastantes trabajos los cuales requieren bastante tiempo y si se aprende pero es un curso duro y de un tiempo de dedicación mas de lo esperado'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, '053f270c88062549d67f89777002c7e0a1bdabd842c625922425c82d390ff82e'::TEXT, ARRAY[554]::BIGINT[]),
    (147::BIGINT, 'La profesora es muy grosera y piensa que los estudiantes le tienen que recordar las cosas a ella. No explica bien y deja tareas muy largas e innecesarias. Todo se le olvida y se atrasa con notas.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('15','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, '4e8a35674f4064aa7c6c92849b6d4d69622b59a2e1a0f7424542306807ec5576'::TEXT, ARRAY[556, 600, 554]::BIGINT[]),
    (147::BIGINT, 'Es vaga con las notas, es como una profesora de secundaria, a veces molesta. Hace su trabajo, se aprende, no mucho pero se aprende.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-26T00:00:00+00:00'::TIMESTAMPTZ, '9f41cfb6686c2d8a9e11aac25f9a255a68e236711053fd11ec1c960ccb9e5652'::TEXT, ARRAY[554]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
